operation.add:
global $context, $scripturl, $txt;
static $canSearch = null;

// Save the search permission to avoid adding more queries to the db.
// It saves lives (and servers) when there are too many tags to parse.
if ($canSearch === null)
	$canSearch = allowedTo('search_posts');

if (!$context['user']['is_guest'] && $canSearch)
	$tags .= '<a class="threadTag" style="background-color: ' . $color . ';" href="' . $scripturl . '?action=search2;search=' . htmlspecialchars('[' . $tag . ']') . '" title="' . sprintf($txt['sstd_search_tag'], $tag) . '">' . $tag . '</a>';
else
	$tags .= '<span class="threadTag" style="background-color: ' . $color . ';">' . $tag . '</span>';

operation.search:
// Censor it!
censorText($row['subject']);
censorText($row['body']);

$preview = strip_tags(strtr($row['body'], array('<br />' => '&#10;')));

operation.add:
// Make our tags for SSI.
$threadTags = makeThreadTags($row['subject']);

$row['subject'] = $threadTags[0];
$threadTags = $threadTags[1];

operation.search:
// Censor the subject.
censorText($row['subject']);
censorText($row['body']);

if (empty($modSettings['messageIconChecks_disable']) && !isset($icon_sources[$row['icon']]))
	$icon_sources[$row['icon']] = file_exists($settings['theme_dir'] . '/images/post/' . $row['icon'] . '.gif') ? 'images_url' : 'default_images_url';

